"use client";

import { useDroppable } from "@dnd-kit/core";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Question } from "@orksys-survey/db";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { motion } from "framer-motion";
import {
	Bolt,
	Calendar,
	CheckSquare,
	ChevronsUpDown,
	ClipboardList,
	FileText,
	GripVertical,
	Hash,
	ListChecks,
	Mail,
	MoreHorizontal,
	Phone,
	Star,
	Text,
	Trash2,
	TrendingUp,
} from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";

interface QuestionCardProps {
	question: Question;
	isSelected: boolean;
	onSelect: () => void;
	questions: Question[];
	onQuestionsChange: (questions: Question[]) => void;
}

const questionTypeIcons: Record<string, React.ElementType> = {
	text: Text,
	textarea: FileText,
	multiple_choice: CheckSquare,
	checkbox: ListChecks,
	dropdown: ChevronsUpDown,
	rating: Star,
	nps: TrendingUp,
	linear_scale: Hash,
	date: Calendar,
	email: Mail,
	phone: Phone,
	file_upload: ClipboardList,
};

const questionTypeLabels: Record<string, string> = {
	text: "Short Text",
	textarea: "Long Text",
	multiple_choice: "Multiple Choice",
	checkbox: "Checkboxes",
	dropdown: "Dropdown",
	rating: "Rating",
	nps: "NPS",
	linear_scale: "Linear Scale",
	date: "Date",
	email: "Email",
	phone: "Phone",
	file_upload: "File Upload",
};

export function QuestionCard({
	question,
	isSelected,
	onSelect,
	questions,
	onQuestionsChange,
}: QuestionCardProps) {
	const queryClient = useQueryClient();

	// Sortable for reordering within canvas
	const {
		attributes,
		listeners,
		setNodeRef: setSortableRef,
		transform,
		transition,
		isDragging,
	} = useSortable({ id: question.id });

	// Droppable for palette item drops
	const { setNodeRef: setDroppableRef, isOver } = useDroppable({
		id: question.id,
	});

	// Combine refs so element is both sortable and droppable
	const setNodeRef = (node: HTMLElement | null) => {
		setSortableRef(node);
		setDroppableRef(node);
	};

	const deleteMutation = useMutation(
		orpc.question.delete.mutationOptions({
			onSuccess: () => {
				onQuestionsChange(questions.filter((q) => q.id !== question.id));
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question deleted");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to delete question");
			},
		}),
	);

	// Query logic rules to check if this question has any
	const logicRules = useQuery(
		orpc.logicRule.list.queryOptions({
			input: { surveyId: question.surveyId },
		}),
	);

	const hasLogic = logicRules.data?.some(
		(rule) => rule.sourceQuestionId === question.id,
	);

	const style = {
		transform: CSS.Translate.toString(transform), // Use Translate for smoother sorting
		transition,
		zIndex: isDragging ? 50 : undefined,
	};

	const Icon = questionTypeIcons[question.type] || Text;

	return (
		<motion.div
			ref={setNodeRef}
			style={style}
			className={cn(isDragging && "z-50")}
		>
			<Card
				className={cn(
					"cursor-pointer transition-all",
					isSelected && "border-violet-500 ring-1 ring-violet-500",
					isDragging && "opacity-50 shadow-lg",
					isOver && "border-violet-400 border-dashed bg-violet-50",
				)}
				onClick={onSelect}
			>
				<CardContent className="flex items-start gap-3 p-4">
					<button
						type="button"
						className="mt-1 cursor-grab touch-none"
						{...attributes}
						{...listeners}
					>
						<GripVertical className="h-4 w-4 text-neutral-400" />
					</button>

					<motion.div
						className="flex h-8 w-8 shrink-0 items-center justify-center rounded bg-violet-100"
						whileHover={{ scale: 1.05 }}
						transition={{ type: "spring", stiffness: 400, damping: 17 }}
					>
						<Icon className="h-4 w-4 text-violet-600" />
					</motion.div>

					<div className="min-w-0 flex-1">
						<div className="flex items-center gap-2">
							<h3 className="truncate font-medium text-sm">{question.title}</h3>
							{question.required && (
								<motion.span
									initial={{ scale: 0 }}
									animate={{ scale: 1 }}
									className="text-red-500"
								>
									*
								</motion.span>
							)}
							{hasLogic && (
								<motion.span
									initial={{ opacity: 0, scale: 0.8 }}
									animate={{ opacity: 1, scale: 1 }}
									className="flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 font-medium text-[10px] text-violet-600"
								>
									<Bolt className="h-3 w-3" />
									Logic
								</motion.span>
							)}
						</div>
						<p className="mt-0.5 text-neutral-500 text-xs">
							{questionTypeLabels[question.type]}
							{question.description &&
								` • ${question.description.slice(0, 50)}${question.description.length > 50 ? "..." : ""}`}
						</p>
					</div>

					<DropdownMenu>
						<DropdownMenuTrigger
							render={
								<Button
									variant="ghost"
									size="icon"
									className="shrink-0"
									onClick={(e) => e.stopPropagation()}
								/>
							}
						>
							<MoreHorizontal className="h-4 w-4" />
						</DropdownMenuTrigger>
						<DropdownMenuContent align="end">
							<DropdownMenuItem
								className="text-red-600"
								onClick={(e) => {
									e.stopPropagation();
									deleteMutation.mutate({ id: question.id });
								}}
							>
								<Trash2 className="mr-2 h-4 w-4" />
								Delete
							</DropdownMenuItem>
						</DropdownMenuContent>
					</DropdownMenu>
				</CardContent>
			</Card>
		</motion.div>
	);
}

# Fix Drop Indicator: Position-Aware Placement

## Context
The previous implementation attempted to show a drop indicator between question cards, but it doesn't work because:
1. Question cards use `useSortable` (for reordering) but are NOT registered as droppable targets
2. The collision detection only returns "canvas" as the `over.id` - never individual question IDs
3. Therefore `overId` is always "canvas" and `dropIndex` always equals `questions.length`
4. The indicator never shows between cards, and insertion always happens at the end

## Root Cause Analysis
```
Palette Item → Drag → Collision Detection → over.id = "canvas" (only)
                                    ↓
                          overId = "canvas"
                                    ↓
                          dropIndex = questions.length (never a specific index)
                                    ↓
                          Indicator only shows at end
```

The issue is that `useSortable` registers items for sorting within a `SortableContext`, but it doesn't make them droppable targets for cross-container drops from the palette.

## Solution Options

### Option A: Add useDroppable to Question Cards (Chosen)
Make each question card a droppable target in addition to being sortable. This allows collision detection to return the specific question ID when hovering over it.

### Option B: Use Pointer Coordinates
Track the pointer Y position and calculate which question we're over based on bounding rects. More complex but doesn't require modifying question cards.

---

## Implementation (Option A)

### 1. Add Droppable to Question Cards
**File: `question-card.tsx`**

Add `useDroppable` alongside the existing `useSortable`:

```tsx
import { useDroppable } from "@dnd-kit/core";

export function QuestionCard({ question, ... }) {
  // Existing sortable setup
  const {
    attributes,
    listeners,
    setNodeRef: setSortableRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: question.id });

  // NEW: Also make this a droppable target for palette items
  const { setNodeRef: setDroppableRef, isOver } = useDroppable({
    id: question.id,
  });

  // Combine refs
  const setNodeRef = (node: HTMLElement | null) => {
    setSortableRef(node);
    setDroppableRef(node);
  };

  // ... rest of component
}
```

### 2. Update Collision Detection
**File: `index.tsx`**

The current `pointerWithin` should work once question cards are droppables. But we may need to handle the case where pointer is over a question vs the canvas area.

```tsx
const collisionDetection: CollisionDetection = (args) => {
  if (args.active.data.current?.questionType) {
    // For palette items, use pointerWithin to detect specific question cards
    const pointerCollisions = pointerWithin(args);
    if (pointerCollisions.length > 0) {
      // Return the first collision (the question we're over)
      return pointerCollisions;
    }
  }
  return closestCenter(args);
};
```

### 3. Fix handleDragEnd to Use Correct Order
**File: `index.tsx`**

The current logic has an issue: when we insert at `targetIndex`, the backend might not shift existing items. Need to verify the backend handles this, or adjust the order after insertion.

Current problematic code:
```tsx
// This creates at order: targetIndex, but doesn't shift existing items
createMutation.mutate({
  order: targetIndex,
});
```

Should be:
```tsx
// Insert at position - backend should handle shifting
// OR we need to reorder all items after insertion
```

### 4. Update Indicator Logic in Canvas
**File: `builder-canvas.tsx`**

The current logic is correct IF `overId` contains actual question IDs:

```tsx
const dropIndex = overId
  ? safeQuestions.findIndex((q) => q.id === overId)
  : safeQuestions.length;
```

This will now work correctly when `overId` is a question ID instead of "canvas".

---

## Critical Files
- `apps/web/src/components/survey-builder/question-card.tsx` - Add useDroppable
- `apps/web/src/components/survey-builder/index.tsx` - Verify collision detection

---

## Implementation Order
1. Add `useDroppable` to QuestionCard alongside `useSortable`
2. Combine refs so both hooks work on the same element
3. Test that `overId` now contains actual question IDs
4. Verify indicator appears at correct position
5. Verify insertion happens at correct position

---

## Verification
- [ ] Drag from palette over question 1 → overId = question1.id
- [ ] Drag from palette over question 2 → overId = question2.id
- [ ] Drop indicator appears BEFORE the hovered question
- [ ] Drop on question 2 → new question becomes position 2
- [ ] Drop indicator at bottom when not over any question
- [ ] Existing reordering still works

